sys_variable_value.value:
(function execute(inputs, outputs) {

    var gr = new GlideRecord('x_gegis_ins_policy_case_task');
    gr.addQuery('submission', inputs.param_submission);
    gr.addQuery('u_module', inputs.param_module);
    gr.addQuery('u_type', inputs.param_activity);
    gr.query();
    if (gr.next()) {
        outputs.taskrecord = gr;
    } else {
   
        var newTask = new GlideRecord('x_gegis_ins_policy_case_task');
        newTask.initialize();
        newTask.setValue('submission', inputs.param_submission.sys_id);
        newTask.setValue('u_module', inputs.param_module.toString());
        newTask.setValue('u_type', inputs.param_activity.toString());
        newTask.setValue('category', 'case');
        newTask.setValue('state', inputs.param_state);
        if (inputs.param_assigned_to) {
            newTask.setValue('assigned_to', inputs.param_assigned_to.sys_id);
        }
        if (inputs.param_assignment_group) {
            newTask.setValue('assignment_group', inputs.param_assignment_group.sys_id);
        }

        var newSysId = newTask.insert();

        if (newSysId) {
           outputs.taskrecord = newTask;
        } else {
            gs.warn('Failed to insert new Task record');
        }
    }
})(inputs, outputs);

